"use strict";

var scriptLaunched = false;

console.log('script.js loaded and function called');
['DOMContentLoaded', 'DOMLazyLoad'].forEach(event => {
    document.addEventListener(event, () => {
        if(scriptLaunched) return;
        scriptLaunched = true;

        const headerHeight = document.querySelector('.header').offsetHeight; // Позиция элемента с учетом высоты header
        const firstSection = document.querySelector('main section');

        if (!firstSection.classList.contains('single-content')) {
            firstSection.style.marginTop = headerHeight + 'px';
        }

        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', e => {
                e.preventDefault(); // Определяем целевой элемент по якорю
                const targetId = anchor.getAttribute('href');
                const targetElement = document.querySelector(targetId);
                if (targetElement) { // Высота header
                    const targetPosition = targetElement.getBoundingClientRect().top + window.scrollY - (headerHeight + 30); // Плавный скролл
                    window.scrollTo({ top: targetPosition, behavior: 'smooth' });
                }
            });
        });

        const onresize = (dom_elem, callback) => {
            const resizeObserver = new ResizeObserver(() => callback() );
            resizeObserver.observe(dom_elem);
        };

        onresize(firstSection, function () {
            const headerHeight = document.querySelector('.header').offsetHeight; // Позиция элемента с учетом высоты header
            if (!firstSection.classList.contains('single-content')) {
                firstSection.style.marginTop = headerHeight + 'px';
            } else if (window.innerWidth < 770) {
                firstSection.style.marginTop = headerHeight + 'px';
            }
        });

        const language = document.documentElement.lang;
        const language__menu = document.querySelectorAll('.language__menu a');

        if ( language__menu.length > 1 ) {
            if(language === 'de-DE') {
                language__menu[1].classList.add('_active');
            } else {
                language__menu[0].classList.add('_active');
            }
        }


        let canRunSwiper = false;
        let interval =setInterval(() => {
            if (typeof Swiper === 'function') {
                canRunSwiper = true;
            }
            if(canRunSwiper) {
                clearInterval(interval);
                const swiper = new Swiper('.stories__slider', {
                    slidesPerView: 1,
                    navigation: {
                        nextEl: '.swiper-button-next',
                        prevEl: '.swiper-button-prev',
                    },
                });
                const swiperBlocks = document.querySelectorAll('.block-logo__slider')
                for (const swiperBlock of swiperBlocks){
                    new Swiper(swiperBlock, {
                        centeredSlides: true,
                        loop: true,
                        slidesPerView: 'auto',
                        freeMode: {
                            enabled: true,
                            sticky: true,
                            momentumVelocityRatio: 5,
                            momentum: false,
                            minimumVelocity: 0,
                            momentumBounce: true,
                        },
                        speed: 5000,
                        autoplay: {
                            delay: 1,
                        },
                        breakpoints: {
                            // when window width is >= 320px
                            320: {
                                slidesPerView: 'auto',
                                centeredSlides: false,
                            },
                            576: {
                                slidesPerView: 'auto',
                                centeredSlides: false,
                                },
                            // when window width is >= 480px
                            744: {
                                slidesPerView: 'auto',
                            },
                            // when window width is >= 640px
                            990: {
                                slidesPerView: 'auto',
                            }
                            }
                    });
                }
            }
        }, 500);
        
        //Burger
    
        function burgerClick() {
            const burger = document.querySelector('.header__burger');
            const menu = document.querySelector('.bottom-header__nav');
            const btns = document.querySelectorAll('.bottom-header__btns');
            const phones = document.querySelector('.bottom-header_phones');
            const btn_sing_in = document.querySelector('#sing-in-btn');
            const bottom_header__btns_blok = document.querySelector('#bottom-header__btn');
            const body = document.body;
    
            const menuMobile = document.createElement('div');
            menuMobile.classList.add('menu-mobile');
    
            if (burger) {
                burger.addEventListener('click', () => {
                    burger.classList.toggle('_active');
                    body.classList.toggle('_active');
                    menuMobile.classList.toggle('_active');
                });
    
                if (document.documentElement.clientWidth <= 1387) {
                    burger.insertAdjacentElement('afterend', menuMobile);
                    menuMobile.insertAdjacentElement('beforeend', menu);
                    btns.forEach(btn => {
                        menuMobile.insertAdjacentElement('beforeend', btn);
                    });
    
                    bottom_header__btns_blok.insertAdjacentElement('beforeend', btn_sing_in);
                    menuMobile.insertAdjacentElement('beforeend', phones);
                }
            }
        }
    
        burgerClick();
    
        //==============================================================
    
    
        // Menu mobile nav click
    
        function menuClickNavMobile() {
            const links = document.querySelectorAll('.bottom-header__nav-arrow>a');
            const menuListSecond = document.querySelectorAll('.bottom-header__nav-second');
    
            if (links.length > 0) {
                for (let index = 0; index < links.length; index++) {
                    const link = links[index];
                    let secondMenuHeight = menuListSecond[index].clientHeight;
    
                    if (document.documentElement.clientWidth <= 1387) {
                        menuListSecond[index].style.height = '0px';
                    }
    
                    link.addEventListener('click', (e) => {
                        if (document.documentElement.clientWidth <= 1387) {
                            e.preventDefault();
                            link.parentElement.classList.toggle('_active');
    
                            if (link.parentElement.classList.contains('_active')) {
                                menuListSecond[index].style.height = `${secondMenuHeight}px`;
                                menuListSecond[index].style.marginTop = '16px';
                            } else {
                                menuListSecond[index].style.height = '0px';
                                menuListSecond[index].style.marginTop = '0px';
                            }
                        }
                    });
                }
            }
        }

        menuClickNavMobile();
    
        //===================================================================
    
        // Tab Solutions
    
        function tabSolutionHide(tabs, contents) {
            tabs.forEach(tab => {
                tab.classList.remove('_active');
            });
            contents.forEach(content => {
                content.classList.remove('_active');
            });
        }
        function tabSolutionClick(selectorTab, selectorContents) {
            const tabs = document.querySelectorAll(selectorTab);
            const contents = document.querySelectorAll(selectorContents);
            if (tabs.length > 0) {
    
                tabs[0].classList.add('_active');
                contents[0].classList.add('_active');
    
                tabs.forEach((tab, i) => {
                    tab.addEventListener('click', () => {
                        tabSolutionHide(tabs, contents);
                        tab.classList.add('_active');
                        contents[i].classList.add('_active');
                    });
                });
            }
        }
        tabSolutionClick('.solutions__tab', '.solutions__content');
        // tabSolutionClick('.blog-offer__tab', '.blog-content__content');
    
        //=========================================================================
    
        //Faq click
    
        function faqItemClick() {
            const items = document.querySelectorAll('.faq__header');
            const itemParents = document.querySelectorAll('.faq__item');
            const itemBodys = document.querySelectorAll('.faq__body');
    
            if (itemParents.length > 0) {
                itemParents.forEach((item, i) => {
                    let bodyHeight = itemBodys[i].clientHeight;
                    itemBodys[i].style.height = '0px';
    
                    item.addEventListener('click', () => {
                        item.classList.toggle('_active');
    
                        if (item.classList.contains('_active')) {
                            itemBodys[i].style.height = `${bodyHeight}px`;
                        } else {
                            itemBodys[i].style.height = '0px';
                        }
                    });
                });
            }
        }
        faqItemClick();
    
        //===================================================================
    
    
        //Footer Language
    
        function footerLangugeClick() {
            const languageHeader = document.querySelectorAll('.bottom-footer__language-header');
            const body = document.body;

            if ( languageHeader.length > 0 ) {
                for (let i = 0; i < languageHeader.length; i++) {

                    languageHeader[i].addEventListener('click',function () {
                        const self = this;
                        const languageBody = self.nextElementSibling;
                        const div = document.createElement('div');

                        body.append(div);
                        languageBody.classList.toggle('_active');

                        if (languageBody.classList.contains('_active')) {
                            div.classList.add('div-body');
                        } else {
                            div.classList.remove('div-body');
                        }
                    });

                }
            }
        }

        footerLangugeClick();
    
        //====================================================================
    
        // Number Index
    
        function numberIndex(selectorItem, stop = false) {
            const numberItem = document.querySelectorAll(selectorItem);
    
            if (numberItem.length > 0) {
                if (stop === false) {
                    for (let index = 0; index < numberItem.length; index++) {
                        const element = numberItem[index];
                        const dataNum = Number(element.dataset.number);
                        const dataNumProcent = Math.round(dataNum * 0.1);
                        let i = dataNumProcent;
    
                        let timer = setInterval(() => {
                            if (i <= dataNum) {
                                element.textContent = i++;
                            }
                            if (i === (dataNum + 1)) {
                                clearInterval(timer);
                            }
                        }, 80);
                    }
                }
            }
        }
        function animatedNumbersIndex() {
            const realize = document.querySelector('.benefits');
    
            if (realize) {
                let isRunning = false;
                let elementPositionRealize = realize.offsetTop;
                let windowHeight = document.documentElement.clientHeight;
                let number = windowHeight / 100 * 50;

                window.addEventListener('resize', () => {
                    elementPositionRealize = realize.offsetTop;
                    windowHeight = document.documentElement.clientHeight;
                    number = windowHeight / 100 * 20;
                });
    
                window.addEventListener('scroll', () => {
                    elementPositionRealize = realize.offsetTop;
                    console.log(window.scrollY + number, elementPositionRealize);
                    if (window.scrollY + number >= elementPositionRealize) {
                        if (!isRunning) {
                            numberIndex('.benefits__number span');
                            isRunning = true
                        }
                    } else {
                        isRunning = false;
                    }
                });
            }
        }
        console.log('animatedNumbersIndex');
        animatedNumbersIndex();
    
    });
});


// Check if the DOMContentLoaded event has already fired; if so, dispatch DOMLazyLoad immediately
if (document.readyState === "interactive" || document.readyState === "complete") {
    var domLazyLoadEvent = new Event('DOMLazyLoad', { bubbles: true, cancelable: true });
    document.dispatchEvent(domLazyLoadEvent);
}